#!/usr/bin/env bash
# Run the nuisance-ladder study: every XML below xml/nuisance_ladder_study/<family>/<variant>/,
# generated by python/scripts/make_nuisance_ladder_study_xmls.py (variants n5..n10 = number of
# floated modeling knobs). Same options and environment as xml/binning_study/run_all.sh; results
# go to OUTPUT_ROOT/nuisance_ladder_study_fit_results/<family>/<variant>/<fit>/.
script_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
STUDY_DIR="${script_dir}" STUDY_NAME="nuisance_ladder_study" exec "${script_dir}/../binning_study/run_all.sh" "$@"
